CustomField.formula:
/* Returns all years from Booked, Reserved, Sold dates as text */
TRIM(
    IF(NOT(ISBLANK( Booking_Date_Time__c )), TEXT(YEAR( Booked_At_Date__c )) & " ", "") &
    IF(NOT(ISBLANK( Reserved_Date_Time__c )), TEXT(YEAR( Reserved_At_Date__c )) & " ", "") &
    IF(NOT(ISBLANK( Sold_Date_Time__c )), TEXT(YEAR( Sold_At_Date__c )), "")
)
